import base64, json, os
from cryptography.hazmat.primitives.asymmetric import ed25519
from cryptography.hazmat.primitives import serialization
from e2ee_backend.crypto import (sign_message, verify_message, CryptoError,
                                identity_fingerprint,
                                SIGNED_MESSAGE_PREFIX)

priv = ed25519.Ed25519PrivateKey.generate()
seed = base64.b64encode(priv.private_bytes(
    serialization.Encoding.Raw, serialization.PrivateFormat.Raw,
    serialization.NoEncryption())).decode()
pub = base64.b64encode(priv.public_key().public_bytes(
    serialization.Encoding.Raw, serialization.PublicFormat.Raw)).decode()
fp = identity_fingerprint(pub)

env = {"session_id": " 会/sess ", "sender_device_id": " dev/一 ",
       "message_id": " m/1 ", "sequence": 3,
       "nonce": base64.b64encode(os.urandom(12)).decode(),
       "ciphertext": base64.b64encode(os.urandom(32)).decode(),
       "extra": "ignored"}
snap_before = json.dumps(env, ensure_ascii=False)
signed = sign_message(env, seed)
assert json.dumps(env, ensure_ascii=False) == snap_before, "input mutated"
assert set(signed) == {"session_id","sender_device_id","message_id","sequence",
                       "nonce","ciphertext","identity_key","signature"}
assert signed["identity_key"] == pub
assert sign_message(env, seed) == signed

msg = (SIGNED_MESSAGE_PREFIX + "\n" + json.dumps(
    {k: env[k] for k in ("ciphertext","message_id","nonce",
                         "sender_device_id","sequence","session_id")},
    sort_keys=True, separators=(",",":"), ensure_ascii=False)).encode()
priv.public_key().verify(base64.b64decode(signed["signature"]), msg)

result = verify_message(signed, " 会/sess ", " dev/一 ", fp)
assert set(result) == set(signed) | {"fingerprint"}
assert result["fingerprint"] == fp
for k, v in signed.items():
    assert result[k] == v

der = priv.public_key().public_bytes(
    serialization.Encoding.DER, serialization.PublicFormat.SubjectPublicKeyInfo)
signed2 = dict(signed, identity_key=base64.b64encode(der).decode())
r2 = verify_message(signed2, " 会/sess ", " dev/一 ", fp)
assert r2["fingerprint"] == fp
assert r2["identity_key"] == signed2["identity_key"]
assert r2["signature"] == signed["signature"]

for name in ("session_id","sender_device_id","message_id","nonce","ciphertext"):
    bad = dict(signed)
    if name in ("nonce","ciphertext"):
        raw = bytearray(base64.b64decode(bad[name])); raw[0] ^= 1
        bad[name] = base64.b64encode(bytes(raw)).decode()
    else:
        bad[name] = bad[name] + "x"
    try:
        verify_message(bad, bad["session_id"], bad["sender_device_id"], fp)
        raise AssertionError(name)
    except CryptoError as e:
        assert e.field == name, (name, e.field)
bad = dict(signed, sequence=4)
try:
    verify_message(bad, bad["session_id"], bad["sender_device_id"], fp)
except CryptoError as e:
    assert e.field == "signature"

try:
    verify_message(signed, "other", " dev/一 ", fp)
except CryptoError as e:
    assert e.field == "session_id"
try:
    verify_message(signed, " 会/sess ", "other", fp)
except CryptoError as e:
    assert e.field == "sender_device_id"

other = ed25519.Ed25519PrivateKey.generate()
ofp = identity_fingerprint(base64.b64encode(other.public_key().public_bytes(
    serialization.Encoding.Raw, serialization.PublicFormat.Raw)).decode())
try:
    verify_message(signed, " 会/sess ", " dev/一 ", ofp)
except CryptoError as e:
    assert e.field == "expected_fingerprint"

try:
    verify_message(signed, " 会/sess ", " dev/一 ", "ABC"*21 + "0")
except CryptoError as e:
    assert e.field == "expected_fingerprint"

for fn in (lambda: sign_message([], seed), lambda: verify_message(None, "s", "d", fp)):
    try:
        fn()
    except CryptoError as e:
        assert e.field == "envelope"

for val in (True, False, 0, -1, 1.0, "1", None):
    try:
        sign_message(dict(env, sequence=val), seed)
    except CryptoError as e:
        assert e.field == "sequence", (val, e.field)
    else:
        raise AssertionError(val)

try:
    sign_message(dict(env, nonce=base64.b64encode(b"x"*11).decode()), seed)
except CryptoError as e:
    assert e.field == "nonce"
try:
    sign_message(dict(env, ciphertext=base64.b64encode(b"x"*15).decode()), seed)
except CryptoError as e:
    assert e.field == "ciphertext"
sign_message(dict(env, ciphertext=base64.b64encode(b"x"*16).decode()), seed)

for bad in ("nope", base64.b64encode(b"\x00"*31).decode(),
            base64.b64encode(b"\x00"*32).decode().rstrip("=")):
    try:
        sign_message(env, bad)
    except CryptoError as e:
        assert e.field == "private_key"

bad = dict(signed, signature=signed["signature"].rstrip("="))
try:
    verify_message(bad, " 会/sess ", " dev/一 ", fp)
except CryptoError as e:
    assert e.field == "signature"
raw = bytearray(base64.b64decode(signed["signature"])); raw[0] ^= 1
bad = dict(signed, signature=base64.b64encode(bytes(raw)).decode())
try:
    verify_message(bad, " 会/sess ", " dev/一 ", fp)
except CryptoError as e:
    assert e.field == "signature"

from cryptography.hazmat.primitives.asymmetric import x25519
xpub = base64.b64encode(x25519.X25519PrivateKey.generate().public_key().public_bytes(
    serialization.Encoding.Raw, serialization.PublicFormat.Raw)).decode()
bad = dict(signed, identity_key=xpub)
try:
    verify_message(bad, " 会/sess ", " dev/一 ", fp)
except CryptoError as e:
    assert e.field == "identity_key"

r3 = verify_message(signed, " 会/sess ", " dev/一 ", fp)
assert r3["fingerprint"] == fp

bad_env = dict(signed); bad_env["session_id"] = ""
try:
    verify_message(bad_env, " 会/sess ", " dev/一 ", fp)
except CryptoError as e:
    assert e.field == "session_id"

# non-canonical base64 with trailing bits / whitespace
for badnonce in (env["nonce"] + " ", "AA==" + " "):
    try:
        sign_message(dict(env, nonce=badnonce), seed)
    except CryptoError as e:
        assert e.field == "nonce", (badnonce, e.field)
print("ALL SMOKE CHECKS PASSED")
